use xiom.io;
type Queue[T] = {
  items: Vec[T];
}

fn Queue.enqueue[T](&mut self, item: T) {
  self.items.push(item);
}

fn Queue.dequeue[T](&mut self) -> Option[T] {
  if self.items.len() == 0 {
    return None;
  };
  let result = self.items.get(0).unwrap().clone();
  self.items.remove(0);
  Some(result)
}

fn main() -> Int {
  var q: Queue[Int] = Queue{ items: Vec[Int].new() };
  q.enqueue(1);
  q.enqueue(2);
  q.enqueue(3);
  let v1 = q.dequeue().unwrap();
  let v2 = q.dequeue().unwrap();
  let v3 = q.dequeue().unwrap();
  io.println(v1.to_str());
  io.println(v2.to_str());
  io.println(v3.to_str());
  return 0;
}
